import{c as a,Q as o,j as n,m as r}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"Not All Errors Are Equal: Consequence-Aware Reasoning Compute Allocation","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.04402","title":"Not All Errors Are Equal: Consequence-Aware Reasoning Compute Allocation","archived_date":"2026-07-25T00:00:00.000Z","arxiv_id":2606.04402,"authors":["Jingbo Wen","Liang He","Ziqi He"],"domain":"consequence-aware-compute-allocation","published_date":"2026-06-03T00:00:00.000Z","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-07-25-consequence-aware-reasoning-compute-allocation-2606-04402.md","filePath":"research/papers/2026-07-25-consequence-aware-reasoning-compute-allocation-2606-04402.md","lastUpdated":1785909234000}'),t={name:"research/papers/2026-07-25-consequence-aware-reasoning-compute-allocation-2606-04402.md"};function c(s,e,l,i,u,p){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="not-all-errors-are-equal-consequence-aware-reasoning-compute-allocation" tabindex="-1">Not All Errors Are Equal: Consequence-Aware Reasoning Compute Allocation <a class="header-anchor" href="#not-all-errors-are-equal-consequence-aware-reasoning-compute-allocation" aria-label="Permalink to &quot;Not All Errors Are Equal: Consequence-Aware Reasoning Compute Allocation&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>本文質疑主流 test-time compute scaling 的隱含假設——「所有錯誤代價相同」。作者提出以輕量預測器估計每個任務答錯後的下游代價，據此（而非單純任務難度）將推理算力路由到更高的 compute tier，在固定總預算下最大化整體效益。在 SWE-bench Lite + Multi-SWE-bench mini 共 700 個軟體工程任務上的實測顯示：consequence 與 difficulty 兩軸近乎正交（現有模型未依代價充分分配算力）；consequence-aware scheduler 相對 difficulty-only routing 降低 cost-weighted loss 22–33%；預測器實作版本可達理論最優的 90% 以上。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p>本文提出的「代價感知」路由範式與 workspace 現有版圖（agent harness／FinOps／SRE）無內容重疊；核心關鍵詞（consequence、compute allocation、test-time scaling 等）於既有覆蓋集合、既有論文標題集合、既探勘新領域紀錄三處反向 grep 命中皆為 0。</p>',5)])])}const h=a(t,[["render",c]]);export{m as __pageData,h as default};
